pub fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    // All input vectors must have the same length
    let n = vals_1.len();
    debug_assert_eq!(vals_2.len(), n, "vals_2 must have the same length as vals_1");
    debug_assert_eq!(conds_1.len(), n, "conds_1 must have the same length as vals_1");
    debug_assert_eq!(conds_2.len(), n, "conds_2 must have the same length as vals_1");

    // Clear any existing contents and prepare space for n elements
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let v1 = vals_1[i];
        let v2 = vals_2[i];
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        // We assume c1 || c2 is always true
        let result = if c1 && c2 {
            // both true: take integer average
            (v1 + v2) / 2
        } else if c1 {
            // only first true
            v1
        } else {
            // only second true
            v2
        };

        avgs.push(result);
    }
}